mapper.select:
SELECT DISTINCT b.task_result_id, f.real_code, b.device_name, b.instance_name, g.cruise_type, h.dict_note as cruise_type_name, g.result_num, g.cruise_result, j.dict_note as cruise_result_name, b.cruise_time, g.cruise_abnormal, p.dict_note as abnormal_type, g.evaluation_state, i.dict_note as evaluation_state_name, g.check_user, g.check_date, g.picpath as pic_path, g.identify_result, w.dict_note as identify_result_name, g.identify_state, g.person_check, b.device_id, g.cruise_data_id, g.cruise_result_id, b.instance_id, e.device_mete_id, q.state_zero, q.state_one, q.high_limit1, q.high_limit2, q.high_limit3, q.high_limit4, q.low_limit1, q.low_limit2, q.low_limit3, q.low_limit4, q.mete_kind, m.dict_note as mete_kind_name, e.cruise_id as preset_id, k.camera_id, b.end_time, g.is_warn, q.alarm_state, q.alarm_level, s.dict_note as alarm_level_name, n.device_type FROM t_cruise_result a LEFT JOIN t_cruise_task_result_detail b on a.task_result_id = b.task_result_id LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device n on n.device_id = b.device_id LEFT JOIN t_std_device_attr f on f.device_id = b.device_id LEFT JOIN t_cruise_data_result g on g.cruise_result_id = b.cruise_result_id LEFT JOIN t_dict_business h on h.dict_code = g.cruise_type and h.col_name = 'cruise_type' LEFT JOIN t_dict_business i on i.dict_code = g.evaluation_state and i.col_name = 'evaluation_state' LEFT JOIN t_dict_business j on j.dict_code = g.cruise_result and j.col_name = 'cruise_result' LEFT JOIN t_dict_business p ON p.dict_code = g.cruise_abnormal and p.col_name = 'abnormal_type' LEFT JOIN t_std_devicemete q on q.device_mete_id = e.device_mete_id LEFT JOIN t_dict_business m on q.mete_kind = m.dict_code and m.col_name ='mete_kind' LEFT JOIN t_camera_preset k on k.preset_id = e.cruise_id LEFT JOIN t_dict_business w on w.dict_code = g.identify_result and w.col_name ='identify_result' LEFT JOIN t_dict_business s on s.dict_code = q.alarm_level and s.col_name ='alarm_level' WHERE 1 = 1 and b.task_result_id = #{taskResultId,jdbcType=VARCHAR}
and n.device_type = #{deviceType, jdbcType=INTEGER}
and g.cruise_type = #{cruiseType, jdbcType=INTEGER}
and cruise_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and g.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
ORDER BY b.device_id,n.custom_id,b.instance_id

mapper.update:
update t_cruise_result a 
a.check_user = #{checkUserName},
a.check_date = #{checkDate, jdbcType=TIMESTAMP}

where a.task_result_id = #{taskResultId, jdbcType=VARCHAR}

UPDATE t_warn_info a 
a.conf_mode = 275,
a.deal_type = 287,
a.deal_info = "程序异常，告警误报",
a.deal_person_id = #{dealPersonId},
a.deal_time = #{dealTime, jdbcType=TIMESTAMP}

WHERE
a.task_id = #{taskId, jdbcType=VARCHAR}
and a.instance_id = #{instanceId,jdbcType = BIGINT}

